mapper.select:
select ETR_ENTRUST.ENTRUST_ID entrustId, ETR_ENTRUST.ENTRUST_STATUS entrustStatus, ETR_ENTRUST.INV_MANAGER_ID invManagerId, ETR_ENTRUST_ADD.ASSET_TYPE1 assetType1, ETR_ENTRUST_ADD.ASSET_TYPE_10 assetType10, ETR_ENTRUST.FINPROD_ID finprodMarketId, ETR_ENTRUST_ADD.SEC_ACCT_ID repFinancier, ETR_ENTRUST_ADD.CONTRACT_NO contractNo, ETR_ENTRUST_ADD.CONTRACT_RESULT contractResult, ROUND (ETR_ENTRUST_ADD.MATURE_YIELD,4) matureYield, ROUND (ETR_ENTRUST.ENTRUST_AMT,2) entrustAmt, ETR_ENTRUST.CCY ccy, DATE_FORMAT(ETR_ENTRUST_ADD.VDATE ,'%Y-%m-%d') vdateStr, DATE_FORMAT(ETR_ENTRUST_ADD.MDATE ,'%Y-%m-%d') mdateStr, ETR_ENTRUST_ADD.VDATE vDate, ETR_ENTRUST_ADD.MDATE mDate from ETR_ENTRUST inner join ETR_ENTRUST_ADD on ETR_ENTRUST_ADD.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID
AND ETR_ENTRUST.FINPROD_TYPE2 = #{finprodType2,jdbcType=VARCHAR} AND NOT EXISTS (SELECT 1 FROM FIN_PRODUCT WHERE FIN_PRODUCT.FINPROD_ID = ETR_ENTRUST.FINPROD_ID)
AND ETR_ENTRUST.FINPROD_ID = #{finprodMarketId,jdbcType=VARCHAR}
AND ETR_ENTRUST_ADD.ASSET_TYPE1 IN
#{item,jdbcType=VARCHAR}
AND ETR_ENTRUST_ADD.ASSET_TYPE_10 IN
#{item,jdbcType=VARCHAR}
AND ETR_ENTRUST.CCY = #{ccy,jdbcType=VARCHAR}
AND ETR_ENTRUST.ENTRUST_STATUS = #{entrustStatus,jdbcType=VARCHAR}
AND ETR_ENTRUST_ADD.SEC_ACCT_ID = #{repFinancier,jdbcType=VARCHAR}
AND ETR_ENTRUST.CREATE_USER = #{userId,jdbcType=VARCHAR}
order by ETR_ENTRUST.ENTRUST_ID desc
